// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GmExecution) predicate.GmExecution {
	return predicate.GmExecution(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GmExecution) predicate.GmExecution {
	return predicate.GmExecution(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GmExecution) predicate.GmExecution {
	return predicate.GmExecution(sql.NotPredicates(p))
}
